CSS = r'''
.distribution{background:var(--white);border:1px solid var(--line);border-radius:10px;padding:18px;margin:18px 0}.distribution-row{display:grid;grid-template-columns:36px 1fr 130px;align-items:center;gap:12px;font-size:13px;margin:8px 0}.distribution-track{height:10px;background:#edf2ed;border-radius:5px;overflow:hidden}.distribution-bar{height:100%;background:var(--green)}
.trend-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:16px 0}.trend-metric{background:var(--white);border:1px solid var(--line);border-radius:10px;padding:16px;min-width:0}.trend-metric h3{margin:0;font-size:13px;color:var(--muted);font-weight:500}.trend-metric strong{display:block;font-size:28px;line-height:1.5;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.trend-metric p{font-size:12px;color:var(--muted);line-height:1.6}.trend-range{border-left:3px solid var(--green);padding:12px 16px;background:#e8f1e5;margin:14px 0}.trend-range strong{display:block}.trend-range p{font-size:13px;margin-top:3px}.trend-context{margin:0 0 8px;font-size:16px;font-weight:650;overflow-wrap:anywhere}
.trend-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:18px 0}.trend-chart{min-width:0;background:var(--white);border:1px solid var(--line);border-radius:10px;padding:16px}.trend-chart h3{font-size:17px;margin:0 0 6px}.trend-chart svg{width:100%;height:auto;display:block;overflow:visible}.trend-chart [role=button]{cursor:pointer}.trend-chart [role=button]:focus{outline:2px solid #153d30;outline-offset:3px}.trend-axis-help{font-size:13px;color:#43584c;line-height:1.7}.trend-legend{font-size:12px;color:#43584c;display:flex;gap:14px;flex-wrap:wrap;margin:8px 0}.trend-legend span{display:inline-flex;align-items:center;gap:5px}.trend-swatch{width:22px;border-top:3px solid #176f53;display:inline-block}.trend-swatch.paid{border-top:3px dashed #b47723}.trend-gaps{font-size:12px;color:#43584c;margin:8px 0 0;padding-left:18px;line-height:1.7;overflow-wrap:anywhere}.trend-gaps li{margin:5px 0}.trend-no-gap{font-size:12px;color:var(--muted);margin:8px 0}.trend-readout{background:#edf2ed;border:1px solid var(--line);border-radius:8px;padding:12px 14px;margin:12px 0 18px;font-size:13px;line-height:1.7}.trend-empty{padding:28px 0;color:var(--muted);font-size:13px}.trend-open{border:1px solid var(--line);border-radius:4px;background:var(--white);color:var(--green);font-size:12px;padding:3px 7px;margin-top:6px}.trend-toolbar select{max-width:440px}#trend-rows td:nth-child(2),#trend-rows td:nth-child(3),#trend-rows td:nth-child(5){white-space:normal;min-width:120px;max-width:220px}.latest-link{display:inline-block;margin-top:6px}
@media(max-width:760px){.trend-grid{grid-template-columns:1fr}.trend-summary{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.trend-metric{padding:12px}.trend-metric strong{font-size:23px}.trend-chart{padding:14px}.distribution-row{grid-template-columns:30px 1fr 108px;gap:7px}.trend-toolbar label{min-width:110px}.trend-toolbar select{max-width:100%}}
'''

HTML = r'''
<section class="panel" id="trends" role="tabpanel" aria-labelledby="tab-trends" hidden>
__OVERVIEW__
<div id="trend-detail" hidden><button type="button" id="overview-back" class="overview-back">← 返回本期图表简报</button><div class="panel-intro"><h2 id="trend-detail-title" tabindex="-1">单产品详情 · 历史趋势</h2><p class="muted">先看当前状态，再看逐日变化。排名越靠近第1名越好；新增评分指数量，不是星级得分或新增用户。</p></div>
<div class="toolbar trend-toolbar"><label>平台<select id="trend-platform"><option value="">全部平台</option><option value="ios">iOS</option><option value="android">Android</option></select></label><label>市场<select id="trend-country"><option value="">全部市场</option><option value="cn">中国</option><option value="us">美国</option><option value="jp">日本</option><option value="gb">英国</option></select></label><label>查找产品<input id="trend-query" type="search" placeholder="产品名称或商店ID…"></label><label>查看产品<select id="trend-app"></select></label><label>时间窗口<select id="trend-window"><option value="7">近7天</option><option value="30" selected>近30天</option></select></label></div>
<p id="trend-count" class="trend-context" aria-live="polite"></p><div class="trend-range" id="trend-range"></div><div id="trend-summary" class="trend-summary" aria-label="截至报告日期的排名与评分"></div>
<div class="trend-grid"><div class="trend-chart"><h3>榜单排名 · 每天第几名</h3><p class="trend-axis-help">横轴：日期；纵轴：榜单名次。第1名在顶部，线向上表示名次变好。</p><div id="rank-legend" class="trend-legend"></div><div id="rank-chart"></div><ul id="rank-gap-info" class="trend-gaps" aria-label="排名断线与无值原因"></ul></div>
<div class="trend-chart"><h3>每日新增评分 · 每天增加多少条</h3><p class="trend-axis-help">横轴：日期；纵轴：新增评分数量（条）。柱子越高，当天新增越多。</p><p id="rating-coverage" class="trend-legend"></p><div id="rating-chart"></div><ul id="rating-gap-info" class="trend-gaps" aria-label="评分日增量无值原因"></ul></div></div>
<div class="toolbar"><label>查看某日数值<select id="trend-inspect-date"></select></label></div><div id="trend-readout" class="trend-readout" role="status" aria-live="polite"></div>
<h3>逐日明细 · 与图中的点和柱子对应</h3><div class="tablewrap"><table><thead><tr><th>日期</th><th>免费榜排名 / 状态</th><th>付费榜排名 / 状态</th><th>累计评分（条）</th><th>当日新增评分（条） / 状态</th></tr></thead><tbody id="trend-rows"></tbody></table></div><div class="notice" id="trend-note"></div></div></section>
'''

JS = r'''
const trendData=data.trends||{},trendSeries=trendData.series||[];
const trendKey=p=>JSON.stringify([p.platform,p.country,p.app_id]);
const numberValue=v=>typeof v==='number'&&Number.isFinite(v);
const rankReasons={off_chart:'未在当日完整榜单前100名',not_returned:'短榜未返回该App，不能据此判断是否离榜',missing:'当日榜单观测缺失或请求失败'};
const ratingReasons={current_missing:'当日累计评分缺失，无法计算',previous_missing:'前一日累计评分缺失，无法计算',count_decreased:'累计评分数回退，不计算负新增'};
const rankState=(r,kind)=>numberValue(r[kind+'_rank'])?'第'+r[kind+'_rank']+'名':(rankReasons[r[kind+'_status']]||'没有可用名次');
const ratingReason=r=>ratingReasons[r.rating_delta_status]||'缺少连续两日有效累计评分，无法计算';
const priorDay=day=>{const d=new Date(day+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-1);return d.toISOString().slice(0,10);};
let activeTrendRows=[];
function chooseTrendDate(day){if(!activeTrendRows.some(r=>r.date===day))return;el('trend-inspect-date').value=day;renderTrendReadout();}
function renderTrendReadout(){const r=activeTrendRows.find(r=>r.date===el('trend-inspect-date').value);el('trend-readout').textContent=r?r.date+'：免费榜'+rankState(r,'free')+'；付费榜'+rankState(r,'paid')+'；累计评分'+(numberValue(r.rating_count)?fmt(r.rating_count)+'条':'缺失')+'；当日新增'+(numberValue(r.rating_delta_1d)?fmt(r.rating_delta_1d)+'条':ratingReason(r))+'。点击图中的点或柱子、用键盘聚焦后按回车，也可选择日期核对。':'';}
function metric(label,value,note){const card=node('article',null,'trend-metric');card.append(node('h3',label),node('strong',value),node('p',note));el('trend-summary').append(card);}
function renderTrendSummary(p,rows){el('trend-summary').replaceChildren();const today=p.observations.find(r=>r.date===data.as_of),before=p.observations.find(r=>r.date===priorDay(data.as_of));for(const [kind,label]of [['free','免费榜当前排名'],['paid','付费榜当前排名']]){let value='无可用名次',note=today?rankState(today,kind):'报告日期没有观测';if(today&&numberValue(today[kind+'_rank'])){value='第'+today[kind+'_rank']+'名';if(before&&numberValue(before[kind+'_rank'])){const gain=before[kind+'_rank']-today[kind+'_rank'];note=gain>0?'较昨日上升'+gain+'名（'+before[kind+'_rank']+'→'+today[kind+'_rank']+'）':gain<0?'较昨日下降'+Math.abs(gain)+'名（'+before[kind+'_rank']+'→'+today[kind+'_rank']+'）':'较昨日持平';}else note='昨日无可比名次，不推算升降';}metric(label,value,note);}
metric('累计评分数量',today&&numberValue(today.rating_count)?fmt(today.rating_count)+'条':'今日缺失','截至'+data.as_of+'；商店累计评分条数');let note=today?ratingReason(today):'报告日期没有观测';if(today&&numberValue(today.rating_delta_1d)){note='与前一天累计评分相比增加的数量';if(before&&numberValue(before.rating_delta_1d)){const d=today.rating_delta_1d-before.rating_delta_1d;note='昨日新增'+fmt(before.rating_delta_1d)+'条；今日'+(d>0?'多'+fmt(d)+'条':d<0?'少'+fmt(-d)+'条':'与昨日相同');}}metric('今日新增评分',today&&numberValue(today.rating_delta_1d)?fmt(today.rating_delta_1d)+'条':'无法计算',note);}
function describeDates(days){if(days.length<=5)return days.map(d=>d.slice(5)).join('、');return days[0].slice(5)+'至'+days[days.length-1].slice(5)+'期间共'+days.length+'天（详见逐日明细）';}
function gapLine(id,text){el(id).append(node('li',text));}
function renderGapInfo(rows,fields){el('rank-gap-info').replaceChildren();el('rating-gap-info').replaceChildren();for(const [field,,label]of fields){const kind=field.startsWith('free')?'free':'paid',valid=rows.filter(r=>numberValue(r[field])).length;if(!valid)gapLine('rank-gap-info',label+'：本窗口没有排名记录，因此不显示该系列。');for(const [state,reason]of Object.entries(rankReasons)){const days=rows.filter(r=>!numberValue(r[field])&&r[kind+'_status']===state).map(r=>r.date);if(days.length)gapLine('rank-gap-info',label+' · '+describeDates(days)+'：'+reason+'。'+(valid?'该日期不画排名点，折线断开。':'不补为第100名或0。'));}}
if(!el('rank-gap-info').childNodes.length)gapLine('rank-gap-info','本窗口有完整逐日排名，没有断线。');for(const [state,reason]of Object.entries(ratingReasons)){const days=rows.filter(r=>!numberValue(r.rating_delta_1d)&&(r.rating_delta_status===state||(!r.rating_delta_status&&state==='previous_missing'))).map(r=>r.date);if(days.length)gapLine('rating-gap-info',describeDates(days)+'：'+reason+'；该日不画柱子，不补为0。');}if(!el('rating-gap-info').childNodes.length)gapLine('rating-gap-info','本窗口每天均可计算日增量；0条会保留为0。');}
function drawTrend(id,rows,fields,inverted){const host=el(id);host.replaceChildren();const vals=rows.flatMap(r=>fields.map(([f])=>r[f])).filter(numberValue);if(!vals.length){host.append(node('p','该窗口没有可绘制的数值，原因见下方说明与逐日明细。','trend-empty'));return;}
const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg'),W=Math.max(280,Math.round(host.clientWidth||560)),H=W<420?270:265,L=52,R=18,T=34,B=57;svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.setAttribute('role','group');svg.setAttribute('aria-label',inverted?'排名图：横轴日期，纵轴榜单名次，第1名在顶部':'新增评分柱状图：横轴日期，纵轴每日新增评分数量（条）');const ymax=inverted?100:Math.max(1,...vals),xx=i=>L+(rows.length===1?(W-L-R)/2:i*(W-L-R)/(rows.length-1)),yy=v=>inverted?T+(v-1)/99*(H-T-B):H-B-v/ymax*(H-T-B);
function shape(tag,attrs,text){const n=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,String(v));if(text!==undefined)n.textContent=text;svg.append(n);return n;}
shape('text',{x:L,y:17,'font-size':12,fill:'#43584c'},inverted?'纵轴：榜单名次':'纵轴：新增评分（条）');shape('text',{x:(L+W-R)/2,y:H-6,'text-anchor':'middle','font-size':12,fill:'#43584c'},'横轴：日期（月-日）');
const ticks=inverted?[1,25,50,75,100]:[...new Set([0,Math.round(ymax/2),ymax])];for(const v of ticks){const y=yy(v);shape('line',{x1:L,y1:y,x2:W-R,y2:y,stroke:'#d8e3dc'});shape('text',{x:L-7,y:y+4,'text-anchor':'end','font-size':12,fill:'#43584c'},inverted?'#'+v:fmt(v));}
const barSlot=(W-L-R)/Math.max(1,rows.length),barX=i=>L+barSlot*(i+.5);const dateTicks=W<420?[0,Math.floor((rows.length-1)/2),rows.length-1]:[0,Math.floor((rows.length-1)/3),Math.floor(2*(rows.length-1)/3),rows.length-1];for(const i of [...new Set(dateTicks)])shape('text',{x:inverted?xx(i):barX(i),y:H-B+23,'text-anchor':'middle','font-size':12,fill:'#43584c'},rows[i].date.slice(5));
function selectable(n,row,value,label){n.setAttribute('tabindex','0');n.setAttribute('role','button');n.setAttribute('aria-label',row.date+'，'+label+(inverted?'第'+value+'名':value+'条')+'，按回车查看当日明细');n.setAttribute('data-date',row.date);n.setAttribute('data-value',value);const title=document.createElementNS(ns,'title');title.textContent=row.date+' · '+label+' · '+(inverted?'第'+value+'名':value+'条');n.append(title);n.addEventListener('click',()=>chooseTrendDate(row.date));n.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();chooseTrendDate(row.date);}});}
for(const [field,color,label]of fields){if(inverted){let part=[];function flush(){if(part.length>1)shape('polyline',{points:part.join(' '),fill:'none',stroke:color,'stroke-width':2.5,'stroke-dasharray':field==='paid_rank'?'6 4':'none'});part=[];}rows.forEach((r,i)=>{if(!numberValue(r[field])){flush();return;}part.push(xx(i)+','+yy(r[field]));});flush();rows.forEach((r,i)=>{if(!numberValue(r[field]))return;const dot=shape('circle',{cx:xx(i),cy:yy(r[field]),r:4.5,fill:color,stroke:'#fff','stroke-width':1});selectable(dot,r,r[field],label);});}
else{const barWidth=Math.max(4,Math.min(30,barSlot*.62));rows.forEach((r,i)=>{const v=r[field];if(!numberValue(v))return;const x=barX(i),y=yy(v),bar=shape(v===0?'circle':'rect',v===0?{cx:x,cy:y,r:3,fill:color}:{x:x-barWidth/2,y,width:barWidth,height:H-B-y,rx:2,fill:color});selectable(bar,r,v,'当日新增评分');if(rows.length<=10)shape('text',{x,y:Math.max(T-1,y-7),'text-anchor':'middle','font-size':12,fill:'#16302b'},fmt(v));});
}}
host.append(svg);}
function renderTrend(){const p=trendSeries.find(p=>trendKey(p)===el('trend-app').value);for(const id of ['trend-rows','trend-range','trend-summary','rank-chart','rating-chart','rank-legend','rank-gap-info','rating-gap-info','trend-inspect-date','trend-readout'])el(id).replaceChildren();el('rating-coverage').textContent='';activeTrendRows=[];if(!p){el('trend-count').textContent='没有符合条件的产品';return;}
const first=new Date(data.as_of+'T00:00:00Z');first.setUTCDate(first.getUTCDate()-Number(el('trend-window').value)+1);const rows=p.observations.filter(r=>r.date>=first.toISOString().slice(0,10));activeTrendRows=rows;el('trend-detail-title').textContent=p.name+' · 每日排名与评分';el('trend-count').textContent=p.name+' · '+(p.platform==='ios'?'iOS':'Android')+' / '+(names[p.country]||p.country);if(!rows.length){el('trend-range').textContent='所选时间窗口没有观测日期。';return;}
const freeCount=rows.filter(r=>numberValue(r.free_rank)).length,paidCount=rows.filter(r=>numberValue(r.paid_rank)).length,ratingCount=rows.filter(r=>numberValue(r.rating_delta_1d)).length,anyCount=rows.filter(r=>numberValue(r.free_rank)||numberValue(r.paid_rank)||numberValue(r.rating_count)).length;el('trend-range').append(node('strong','实际展示日期：'+rows[0].date+' 至 '+rows[rows.length-1].date+'（'+rows.length+'个日历日）'),node('p','所选窗口：近'+el('trend-window').value+'天；本产品有数值记录'+anyCount+'天。免费榜排名'+freeCount+'/'+rows.length+'天，付费榜排名'+paidCount+'/'+rows.length+'天，评分日增量'+ratingCount+'/'+rows.length+'天。'),node('p','当前状态截至报告日期 '+data.as_of+'；缺失不补零，原因列在各图下方。'));
renderTrendSummary(p,rows);const allFields=[['free_rank','#176f53','免费榜'],['paid_rank','#b47723','付费榜']],rankFields=allFields.filter(([f])=>rows.some(r=>numberValue(r[f])));for(const [f,,label]of rankFields){const item=node('span'),swatch=node('i',null,'trend-swatch'+(f==='paid_rank'?' paid':''));swatch.setAttribute('aria-hidden','true');item.append(swatch,node('span',label+(f==='paid_rank'?'（虚线）':'（实线）')));el('rank-legend').append(item);}el('rating-coverage').textContent=ratingCount+'/'+rows.length+'天可计算日增量；每根柱子代表一天，数值单位为条。';drawTrend('rank-chart',rows,rankFields,true);drawTrend('rating-chart',rows,[['rating_delta_1d','#176f53','新增评分']],false);renderGapInfo(rows,allFields);
for(const r of rows){const tr=node('tr');for(const value of [r.date,rankState(r,'free'),rankState(r,'paid'),numberValue(r.rating_count)?fmt(r.rating_count):'当日累计评分缺失',numberValue(r.rating_delta_1d)?fmt(r.rating_delta_1d):ratingReason(r)])tr.append(node('td',value,'numeric'));el('trend-rows').append(tr);const option=node('option',r.date);option.value=r.date;el('trend-inspect-date').append(option);}el('trend-inspect-date').value=rows[rows.length-1].date;renderTrendReadout();}
function populateTrends(preferred){const old=preferred||el('trend-app').value,q=el('trend-query').value.trim().toLowerCase(),ps=trendSeries.filter(p=>(!el('trend-platform').value||p.platform===el('trend-platform').value)&&(!el('trend-country').value||p.country===el('trend-country').value)&&(!q||[p.name,p.app_id].join(' ').toLowerCase().includes(q)));el('trend-app').replaceChildren();for(const p of ps){const o=node('option',p.name+' · '+(p.platform==='ios'?'iOS':'Android')+' / '+(names[p.country]||p.country));o.value=trendKey(p);el('trend-app').append(o);}if(ps.some(p=>trendKey(p)===old))el('trend-app').value=old;renderTrend();}
function openProductTrend(p,windowDays){showTrendDetail();if(windowDays)el('trend-window').value=windowDays;el('trend-platform').value=p.platform;el('trend-country').value=p.country;el('trend-query').value='';populateTrends(trendKey(p));activate(el('tab-trends'));el('trend-detail-title').focus();}
for(const id of ['trend-platform','trend-country','trend-query'])el(id).addEventListener(id==='trend-query'?'input':'change',()=>populateTrends());for(const id of ['trend-app','trend-window'])el(id).addEventListener('change',renderTrend);el('trend-inspect-date').addEventListener('change',renderTrendReadout);
el('trend-note').textContent=(trendData.methodology||'尚无历史观测。')+' 排名点和评分柱表示每日采集结果；连线不代表日内实时变化。安卓评分可能全球汇总，所选地区不代表评论作者或评分用户所在地。';populateTrends();
let trendDrawWidth=0;if(typeof ResizeObserver!=='undefined'){const trendResize=new ResizeObserver(entries=>{const width=Math.round(entries[0].contentRect.width);if(width>0&&width!==trendDrawWidth){trendDrawWidth=width;renderTrend();}});trendResize.observe(el('rank-chart'));}
'''
